#!/sbin/sh
# XoomToolkit R22d autonomous boot worker.
# Must be launched by Android init after native config validation.
# Preference file is generated by trusted recovery code; NEVER source it.
BB=/sbin/busybox
CFG=/tmp/xoom-toolkit/boot-flags
STATUS=/tmp/xoom-toolkit/boot/status
MODULE=/sbin/xoom-toolkit-verified-install
bb() { "$BB" "$@"; }
flag() { bb grep -q "^$1=1$" "$CFG" 2>/dev/null; }
note() { bb mkdir -p /tmp/xoom-toolkit/boot; bb echo "$1" > "$STATUS"; }
[ -r "$CFG" ] || { note PREFS_UNAVAILABLE;exit 0; }
[ -x "$MODULE" ] || { note LOADER_MISSING;exit 0; }
[ -d /external_sd/XoomToolkit/packages ] || { note SD_UNAVAILABLE;exit 0; }
note STARTING
wifi=0
if flag wifi_autoload; then
 if "$MODULE" load wifi-runtime; then
  wifi=1
 else
  note WIFI_LOAD_FAILED
 fi
fi
if flag wifi_autorun; then
 if [ "$wifi" -eq 1 ]; then
  # Runtime initialization is distinct from connecting to a network.
  /sbin/setprop xoom.toolkit.wifi.runtime READY
  if flag wifi_autoconnect; then
   if [ -s /external_sd/XoomToolkit/wifi.conf ]; then
    /sbin/xoom-net-control start || note WIFI_AUTOCONNECT_FAILED
   else
    note NO_SAVED_WIFI_PROFILE
   fi
  fi
 else
  note WIFI_AUTORUN_REQUIRES_MODULE
 fi
fi
if flag diag_autoload; then
 if [ "$wifi" -eq 1 ]; then
  if "$MODULE" load network-diagnostics; then
   if flag diag_autorun; then
    /sbin/sh /tmp/XoomToolkit/toolkit/network-diagnostics/diag.sh       > /tmp/xoom-toolkit/boot/diagnostics.log 2>&1 || note DIAGNOSTICS_RUN_FAILED
   fi
  else
   note DIAGNOSTICS_LOAD_FAILED
  fi
 else
  note DIAGNOSTICS_REQUIRES_WIFI
 fi
fi
# Experimental insecure ADB is NEVER started by this general worker.
if flag poc_adb_autoload || flag poc_adb_autorun; then
 bb echo EXPERIMENTAL_ADB_POC_BLOCKED > /tmp/xoom-toolkit/boot/adb-poc.status
fi
note COMPLETED
exit 0
